      "achados": [
        {
          "proposicao": "A fonte indica, como lição aprendida, que o sistema de gestão de segurança operacional deve permanecer funcional durante todo o ciclo de vida da instalação, incluindo a fase de descomissionamento.",
          "trechos": [
            "Eea56a8c8b09d16b8:694:1391"
