      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A fonte reproduz que, em caso de extinção da concessão, o concessionário deve remover por sua conta os equipamentos e bens que não sejam objeto de reversão.",
          "trechos": [
            "Ed6fc440663ca27c4:0:700"
          ],
          "condicoes": [
            "Em qualquer caso de extinção da concessão",
            "Para equipamentos e bens que não sejam objeto de reversão"
          ],
          "limites": [
            "O trecho não define critérios para seleção entre reúso, reciclagem, venda ou descarte",
            "Não há detalhamento de logística, acondicionamento, inventário ou rastreabilidade dos itens removidos"
          ]
        },
        {
          "proposicao": "A mesma passagem indica obrigação de reparar ou indenizar danos decorrentes das atividades e de praticar atos de recuperação ambiental determinados pelos órgãos competentes.",
          "trechos": [
            "Ed6fc440663ca27c4:0:700"
          ],
          "condicoes": [
